@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1946  cases=61
@exercises tuning (tuning), commandManager (h.cmgr), configManager (h.cm), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cmgr:scope, cmgr:installManifest, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-185
  @fn seedItems(h, takes, srcLen)  @ 201-206
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 208-217
  @fn trackList(trackCount)  @ 219-225
  @fn mapBox(tv, take)  @ 228-232
      -- The box the map draws for a take: the travel consumes the window's own shapes.
  @fn mapTracker(harness, inst, trackCount)  @ 237-251
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, the harness behind it for the cmgr, and the page itself.
  @fn chaseTracker(harness)  @ 255-280
      -- A tracker on track 0, bound to 'a0' in its first slot: 'b8' fills the second slot
      -- at QN 8, an audio item lies at 16, and 'c4' sits on the track beside it at 4.

# Cases
  @case 'the manifest declares every command the tracker page registers'  [harness]  @ 287-308
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 312-320
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 323-332
  @case 'focusState before any render returns both bits false'  [harness]  @ 335-342
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 348-361
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 365-382
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 388-409
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 415-433
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 440-458
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 464-497
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 501-525
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 531-561
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 565-586
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 590-603
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 609-643
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 647-661
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 665-688
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 692-728
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 732-767
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 774-791
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 795-818
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 822-845
  @case 'with follow on, the play head carries the tracker across the bound track's slots'  [harness]  @ 851-866
  @case 'with follow off, the head entering another slot leaves the tracker where it was'  [harness]  @ 870-877
  @case 'the chase brackets no loop and raises no map tab'  [harness]  @ 881-896
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 900-935
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 939-987
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 991-1028
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 1032-1066
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 1070-1086
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 1095-1113
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 1117-1133
  @case 'while following, the map window pages off the play head'  [harness]  @ 1137-1147
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1151-1158
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1162-1173
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1177-1200
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1204-1223
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1227-1238
  @case 'a click on a map box travels to its instance, across tracks as well as slots'  [harness]  @ 1242-1281
  @case 'a map box that is no stop refuses the travel, as the walk passes it over'  [harness]  @ 1285-1299
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1303-1312
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1316-1357
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1361-1388
  @case 'while following, the grid pages the scroll to hold the play row'  [harness]  @ 1392-1438
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1442-1466
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1473-1494
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1500-1524
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1531-1550
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1554-1573
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1577-1599
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1605-1623
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1627-1645
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1649-1671
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1675-1686
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1690-1714
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1720-1775
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1783-1812
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1818-1861
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1867-1881
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1888-1920
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1924-1944

